describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 50 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 50 }],
            9.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 2000, costCents: 1000 },
      ],
      1500,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects first bracket at boundary", () => {
      // 500g exactly → first bracket (300)
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    });

    it("selects second bracket when weight exceeds first", () => {
      // 501g → second bracket (600)
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g → third bracket (1000)
      expect(calc.computeShippingCents([makeLine("a", 2000)], 5000)).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 2001g → overflow (1500)
      expect(calc.computeShippingCents([makeLine("a", 2001)], 5000)).toBe(1500);
    });

    it("uses heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      expect(
        calcNoOverflow.computeShippingCents([makeLine("a", 5000)], 1000),
      ).toBe(600);
    });

    it("sums weight across lines and quantities", () => {
      // 200g * 2 + 300g * 1 = 700g → second bracket (600)
      const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → first bracket after sort (500g → 300)
      expect(unordered.computeShippingCents([makeLine("a", 400)], 1000)).toBe(
        300,
      );
    });
  });
});

