});

describe("Cart - checkout()", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(100),
      region: "US",
    });
    cart.add(productA, 2); // subtotal 2000
    cart.add(productB, 1); // subtotal += 2500 → total subtotal 4500
  });

  it("returns totals and lines without collaborators", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4500);
    expect(result.totals.discountCents).toBe(100);
    expect(result.lines).toHaveLength(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1200) // product a
        .mockResolvedValueOnce(2600), // product b
    };
    const result = await cart.checkout({ priceFetcher });
    // New subtotal: 1200*2 + 2600*1 = 5000
    expect(result.totals.subtotalCents).toBe(5000);
    expect(result.lines[0].product.unitPriceCents).toBe(1200);
    expect(result.lines[1].product.unitPriceCents).toBe(2600);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 1 }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.available).toBe(1);
      expect(invErr.requested).toBe(2);
    }
  });

  it("passes inventory check when all items available", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(4500);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal 4500, discount 100, discountedSubtotal 4400
    // tax: floor(4400 * 0.08) = floor(352) = 352
    expect(result.totals.taxCents).toBe(352);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1000),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // All items now 1000 cents: subtotal = 1000*2 + 1000*1 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    // Discount: min(100, 3000) = 100; discountedSubtotal = 2900
    expect(result.totals.discountCents).toBe(100);
    // Tax: floor(2900 * 0.1) = 290
    expect(result.totals.taxCents).toBe(290);
  });

  it("propagates priceFetcher error", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider error", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %s (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it("accepts 0 percent", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
    });

    it("accepts 100 percent", () => {
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 = 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down fractional cents", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → floor = 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("100% returns the entire subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(9999)).toBe(9999);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(10000)).toBe(500);
    });

    it("caps at subtotal when subtotal is smaller", () => {
      const policy = new FixedAmountDiscountPolicy(5000);
      expect(policy.computeDiscountCents(3000)).toBe(3000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns subtotal exactly when they match", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against the original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
        new FixedAmountDiscountPolicy(200), // 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("sum can exceed subtotal (caller clamps)", () => {
      const policies = [
        new PercentageDiscountPolicy(60),
        new PercentageDiscountPolicy(60),
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // 60% + 60% of 1000 = 600 + 600 = 1200 (exceeds 1000)
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(100),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      // 10% of 5000 = 500, + 100 = 600
      expect(composite.computeDiscountCents(5000)).toBe(600);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000 → remaining 9000
        new PercentageDiscountPolicy(10), // 10% of 9000 = 900 → remaining 8100
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("order matters: larger discount first yields more total savings", () => {
      const p20 = new PercentageDiscountPolicy(20);
      const p10 = new PercentageDiscountPolicy(10);

      const bigFirst = new CompositeDiscountPolicy([p20, p10], "chain");
      const smallFirst = new CompositeDiscountPolicy([p10, p20], "chain");

      // bigFirst: 20% of 1000 = 200 → remaining 800; 10% of 800 = 80; total = 280
      expect(bigFirst.computeDiscountCents(1000)).toBe(280);
      // smallFirst: 10% of 1000 = 100 → remaining 900; 20% of 900 = 180; total = 280
      // Actually same here since floor(1000*0.2)=200, floor(800*0.1)=80 vs floor(1000*0.1)=100, floor(900*0.2)=180
      expect(smallFirst.computeDiscountCents(1000)).toBe(280);
    });

    it("chain never exceeds original subtotal", () => {
      const policies = [
        new FixedAmountDiscountPolicy(600),
        new FixedAmountDiscountPolicy(600),
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      // First takes min(600, 1000)=600, remaining=400; second takes min(600,400)=400
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

