import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import {
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator } from "../src/tax.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500, weightGrams: 300 };

describe("Cart - line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("add increases itemCount", () => {
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantity for same product", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for non-positive quantity", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("add throws for non-integer quantity", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true and removes existing product", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity of existing product", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 2)).toThrow(
      "Product unknown is not in the cart",
    );
  });

  it("updateQuantity throws for negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear removes all items", () => {
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart - pricing pipeline", () => {
  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("subtotal is sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2500
    expect(cart.totals().subtotalCents).toBe(4500);
  });

  it("discount is applied then clamped to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped
    expect(totals.totalCents).toBe(0);
  });

  it("negative discount is clamped to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
    });
    cart.add(productA, 1); // subtotal 1000, discount 500, discountedSubtotal 500
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(500, "US");
  });

  it("shipping receives discounted subtotal and lines", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
